CREATE TABLE IF NOT EXISTS `source_accounts` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`integration_id` text,`external_id` text DEFAULT '' NOT NULL,`name` text NOT NULL,`account_type` text DEFAULT 'sub_account' NOT NULL,`status` text DEFAULT '未检测' NOT NULL,`metadata_json` text DEFAULT '{}' NOT NULL,`last_synced_at` text,`last_error` text DEFAULT '' NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `api_endpoints` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`integration_id` text,`key` text NOT NULL,`name` text NOT NULL,`method` text DEFAULT 'GET' NOT NULL,`path` text NOT NULL,`category` text DEFAULT '数据查询' NOT NULL,`description` text DEFAULT '' NOT NULL,`parameter_schema` text DEFAULT '{}' NOT NULL,`response_schema` text DEFAULT '{}' NOT NULL,`enabled` integer DEFAULT 1 NOT NULL,`last_tested_at` text,`last_error` text DEFAULT '' NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `metric_definitions` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`key` text NOT NULL,`name` text NOT NULL,`description` text DEFAULT '' NOT NULL,`unit` text DEFAULT '' NOT NULL,`aggregation` text DEFAULT 'sum' NOT NULL,`formula` text DEFAULT '' NOT NULL,`format` text DEFAULT 'number' NOT NULL,`aliases_json` text DEFAULT '[]' NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `metric_bindings` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`metric_id` text NOT NULL,`endpoint_id` text,`source_id` text,`source_field` text NOT NULL,`dimensions_json` text DEFAULT '[]' NOT NULL,`transform_json` text DEFAULT '{}' NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `uploaded_assets` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`file_name` text NOT NULL,`content_type` text DEFAULT '' NOT NULL,`size` integer DEFAULT 0 NOT NULL,`r2_key` text NOT NULL,`status` text DEFAULT '已上传' NOT NULL,`summary_json` text DEFAULT '{}' NOT NULL,`created_by` text DEFAULT '' NOT NULL,`created_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `agent_runs` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`prompt` text NOT NULL,`status` text DEFAULT '排队中' NOT NULL,`engine` text DEFAULT '规则引擎' NOT NULL,`date_start` text,`date_end` text,`query_plan_json` text DEFAULT '{}' NOT NULL,`report_spec_json` text DEFAULT '{}' NOT NULL,`progress` integer DEFAULT 0 NOT NULL,`error` text DEFAULT '' NOT NULL,`created_by` text DEFAULT '' NOT NULL,`created_at` text NOT NULL,`finished_at` text);
CREATE TABLE IF NOT EXISTS `agent_steps` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`run_id` text NOT NULL,`step_order` integer NOT NULL,`name` text NOT NULL,`status` text DEFAULT '待执行' NOT NULL,`detail` text DEFAULT '' NOT NULL,`started_at` text,`finished_at` text);
CREATE TABLE IF NOT EXISTS `report_versions` (`id` text PRIMARY KEY NOT NULL,`project_id` text NOT NULL,`run_id` text,`title` text NOT NULL,`period_start` text,`period_end` text,`status` text DEFAULT '草稿' NOT NULL,`report_spec_json` text DEFAULT '{}' NOT NULL,`html` text DEFAULT '' NOT NULL,`source_manifest_json` text DEFAULT '{}' NOT NULL,`created_by` text DEFAULT '' NOT NULL,`created_at` text NOT NULL);
CREATE INDEX IF NOT EXISTS `idx_source_accounts_project` ON `source_accounts` (`project_id`,`updated_at`);
CREATE INDEX IF NOT EXISTS `idx_api_endpoints_project_key` ON `api_endpoints` (`project_id`,`key`);
CREATE INDEX IF NOT EXISTS `idx_metric_definitions_project_key` ON `metric_definitions` (`project_id`,`key`);
CREATE INDEX IF NOT EXISTS `idx_metric_bindings_project_metric` ON `metric_bindings` (`project_id`,`metric_id`);
CREATE INDEX IF NOT EXISTS `idx_uploaded_assets_project_created` ON `uploaded_assets` (`project_id`,`created_at`);
CREATE INDEX IF NOT EXISTS `idx_agent_runs_project_created` ON `agent_runs` (`project_id`,`created_at`);
CREATE INDEX IF NOT EXISTS `idx_agent_runs_active` ON `agent_runs` (`project_id`,`status`) WHERE `status` IN ('排队中','运行中');
CREATE INDEX IF NOT EXISTS `idx_agent_steps_run_order` ON `agent_steps` (`run_id`,`step_order`);
CREATE INDEX IF NOT EXISTS `idx_report_versions_project_created` ON `report_versions` (`project_id`,`created_at`);
PRAGMA optimize;
